/**
 * Cognitive Complexity, the language-neutral half.
 *
 * The rules are G. Ann Campbell's, "Cognitive Complexity: A New Way of
 * Measuring Understandability", SonarSource, 2018
 * (https://www.sonarsource.com/docs/CognitiveComplexity.pdf):
 *
 *   structural  +1, plus one per level of nesting it sits inside:
 *               if, ternary, switch, every loop, catch
 *   hybrid      +1, no nesting charge, but the body is one level deeper:
 *               else if / elif, else
 *   fundamental +1, never a nesting charge:
 *               each run of the same boolean operator (a && b && c is one,
 *               a && b || c is two), each method in a recursion cycle,
 *               break LABEL / continue LABEL
 *   nesting     one level deeper inside every structure above, and inside
 *               every nested function or lambda (which is not itself an
 *               increment)
 *   nothing     try, finally, with, return, plain break and continue,
 *               null-coalescing (?? and ?.), the method itself
 *
 * Every language walker is written against this counter so the arithmetic
 * lives in one place and the walkers only say what each node is.
 *
 * Two numbers come out of one walk:
 *
 *   campbell   the whitepaper's rule for boolean runs: one per run
 *   mbcc       MikeVan's Better Cognitive Complexity: Campbell's rule with
 *              one change, applied in two places. Where order carries
 *              meaning, the reader pays per step.
 *
 *              Ordered operands: a boolean run counts one only when its
 *              operands are independent and pure. When order carries
 *              meaning, it counts one per operand, because the reader must
 *              trace the short-circuit to understand the code. Order
 *              carries meaning when any operand contains a call or an
 *              assignment, or when a later operand reaches into (member
 *              access, subscript) a name an earlier operand mentioned.
 *
 *              Ordered branches: in an if / elif / else chain whose branches
 *              test different facts, the k-th branch costs k plus the
 *              nesting charge, because the reader can only understand the
 *              third branch by holding the failure of the first two. A
 *              chain that tests one value against constants (`kind == "a"`,
 *              `elif kind == "b"`, ...) is exclusive by inspection and is a
 *              switch in disguise: it costs one plus nesting for the whole
 *              chain, as a switch does, and the boolean `or` runs inside
 *              its conditions are case lists and cost nothing. Tangle
 *              measures depth; a flat chain has depth 1 however long it is.
 *
 * Everything else is identical between the two, so the difference between
 * them is exactly the cost of order in the function: ordered boolean logic
 * plus ordered branch chains.
 */
import type { Node } from 'web-tree-sitter';

export interface CognitiveScore {
  /** Cognitive Complexity as published by Campbell. */
  campbell: number;
  /** MikeVan's Better Cognitive Complexity: the ordered-operand rule for boolean runs. */
  mbcc: number;
}

/** What a language walker must be able to say about an expression. */
export interface BooleanRules {
  /**
   * When the node is a binary boolean operator, its operator text and its
   * two operands; otherwise null. `not` / `!` and parentheses are not
   * boolean operators: their inner expression is a fresh sequence.
   */
  booleanParts(node: Node): { operator: string; left: Node; right: Node } | null;
  /** True for a call, an assignment, or anything else with an effect or a cost. */
  isImpure(node: Node): boolean;
  /** For member access or subscript, the leftmost identifier; otherwise null. */
  memberRoot(node: Node): string | null;
  /** The name of a bare identifier; otherwise null. */
  identifierName(node: Node): string | null;
  /** Node types the operand scan must not descend into (nested functions, blocks). */
  stopsAt(node: Node): boolean;
  /**
   * When the condition is an exclusive test on one value (`x == CONST`,
   * `x is None`, or an `or` run of such tests on the same x), the text of
   * that value, so a chain can be recognised as a switch in disguise;
   * otherwise null. What counts as a constant is the walker's call and is
   * listed in docs/measures.md.
   */
  exclusiveKey(condition: Node): string | null;
}

/** How a boolean run is charged: both numbers, or Campbell only (case lists in an exclusive chain). */
export type RunCharge = 'both' | 'campbell';

export class CognitiveCounter {
  private campbell = 0;
  private mbcc = 0;

  constructor(private readonly rules: BooleanRules) {}

  get score(): CognitiveScore {
    return { campbell: this.campbell, mbcc: this.mbcc };
  }

  /** if, ternary, switch, loop, catch: +1 and one more per level of nesting. */
  structural(nesting: number): void {
    this.campbell += 1 + nesting;
    this.mbcc += 1 + nesting;
  }

  /** Recursion, labelled break / continue, a loop `else`: costs one with no nesting charge. */
  fundamental(): void {
    this.campbell += 1;
    this.mbcc += 1;
  }

  /**
   * One if / elif / else chain with `branches` branches (the final `else`
   * counts as one). Campbell: the `if` is structural, every later branch is
   * hybrid, so 1 + nesting + (branches - 1). MBCC, ordered branches: the
   * k-th branch costs k + nesting. MBCC, exclusive chain: 1 + nesting for
   * the whole chain, the switch rule. A chain of one branch is a plain if
   * and scores the same under every rule.
   */
  branchChain(branches: number, nesting: number, exclusive: boolean): void {
    this.campbell += 1 + nesting + (branches - 1);
    if (exclusive || branches === 1) {
      this.mbcc += 1 + nesting;
      return;
    }
    for (let k = 1; k <= branches; k += 1) {
      this.mbcc += k + nesting;
    }
  }

  /**
   * Scores one boolean sequence: the node must be a boolean operator. The
   * left-deep tree is flattened into source order and split into runs of
   * the same operator; each run costs one (Campbell) or, when order
   * matters, one per operand (MBCC). Returns the leaf operands so the
   * walker can keep going into them: a parenthesised or negated operand,
   * a call argument, or a ternary may hold a sequence of its own, and
   * those are separate sequences by the whitepaper's rule.
   */
  booleanSequence(node: Node, charge: RunCharge = 'both'): Node[] {
    const operands: Node[] = [];
    const operators: string[] = [];
    const flatten = (n: Node): void => {
      const p = this.rules.booleanParts(n);
      if (!p) {
        operands.push(n);
        return;
      }
      flatten(p.left);
      operators.push(p.operator);
      flatten(p.right);
    };
    flatten(node);
    if (operators.length === 0) {
      return operands;
    }
    // Runs of the same operator. An operand at a boundary belongs to both runs.
    let start = 0;
    for (let i = 1; i <= operators.length; i += 1) {
      if (i === operators.length || operators[i] !== operators[start]) {
        const runOperands = operands.slice(start, i + 1);
        this.campbell += 1;
        if (charge === 'both') {
          this.mbcc += this.orderMatters(runOperands) ? runOperands.length : 1;
        }
        start = i;
      }
    }
    return operands;
  }

  /**
   * The MBCC rule. A run of operands is ordered when any operand is
   * impure, or when a later operand reaches into a name that an earlier
   * operand mentioned: `m is not None and m.dues is not None` is ordered,
   * `is_active and is_paid and is_adult` is not.
   */
  private orderMatters(operands: Node[]): boolean {
    const seen = new Set<string>();
    for (const operand of operands) {
      let impure = false;
      let reachesIntoEarlier = false;
      const names = new Set<string>();
      const visit = (n: Node): void => {
        if (this.rules.stopsAt(n)) {
          return;
        }
        if (this.rules.isImpure(n)) {
          impure = true;
        }
        const root = this.rules.memberRoot(n);
        if (root !== null && seen.has(root)) {
          reachesIntoEarlier = true;
        }
        const id = this.rules.identifierName(n);
        if (id !== null) {
          names.add(id);
        }
        for (const child of n.namedChildren) {
          if (child) {
            visit(child);
          }
        }
      };
      visit(operand);
      if (impure || reachesIntoEarlier) {
        return true;
      }
      for (const name of names) {
        seen.add(name);
      }
    }
    return false;
  }
}

/**
 * Recursion cycles by name within one file. Every function is a node; an
 * edge is a call to a function name that exists in the file. Each function
 * on a cycle (including a function that calls itself) gets one increment.
 * Cross-file recursion and dynamic dispatch are invisible to this and are
 * left uncounted; docs/measures.md says so.
 */
export function functionsInRecursionCycles(calls: Map<string, Set<string>>): Set<string> {
  const onCycle = new Set<string>();
  const reachable = (from: string, target: string): boolean => {
    const stack = [from];
    const visited = new Set<string>();
    while (stack.length > 0) {
      const current = stack.pop()!;
      for (const next of calls.get(current) ?? []) {
        if (next === target) {
          return true;
        }
        if (!visited.has(next) && calls.has(next)) {
          visited.add(next);
          stack.push(next);
        }
      }
    }
    return false;
  };
  for (const name of calls.keys()) {
    if (reachable(name, name)) {
      onCycle.add(name);
    }
  }
  return onCycle;
}

/**
 * Function finders, for callers that do not already walk the tree
 * themselves. DeepTest keeps its own walk (it needs routes and depth as
 * well); UntangleIt and the tests use these. Names follow the same
 * conventions DeepTest prints: a Python def by its name, a TypeScript
 * declaration or method by its name, an arrow or function expression by
 * the variable, property, or field it is assigned to, else "<anonymous>".
 */
import type { Node } from 'web-tree-sitter';
import { MeasuredFunction } from './types';

const TS_FUNCTION_TYPES = new Set(['function_declaration', 'function_expression', 'arrow_function', 'method_definition', 'generator_function', 'generator_function_declaration', 'function']);

export function findPythonFunctions(root: Node): MeasuredFunction[] {
  const out: MeasuredFunction[] = [];
  const visit = (n: Node): void => {
    if (n.type === 'function_definition') {
      out.push({ name: n.childForFieldName('name')?.text ?? '<lambda>', node: n });
    }
    for (const child of n.namedChildren) {
      if (child) {
        visit(child);
      }
    }
  };
  visit(root);
  return out;
}

function typeScriptName(fn: Node): string {
  const own = fn.childForFieldName('name');
  if (own) {
    return own.text;
  }
  const parent = fn.parent;
  if (parent?.type === 'variable_declarator') {
    return parent.childForFieldName('name')?.text ?? '<anonymous>';
  }
  if (parent?.type === 'pair') {
    return parent.childForFieldName('key')?.text ?? '<anonymous>';
  }
  if (parent?.type === 'assignment_expression') {
    return parent.childForFieldName('left')?.text ?? '<anonymous>';
  }
  if (parent?.type === 'public_field_definition' || parent?.type === 'field_definition') {
    return parent.childForFieldName('name')?.text ?? '<anonymous>';
  }
  return '<anonymous>';
}

export function findTypeScriptFunctions(root: Node): MeasuredFunction[] {
  const out: MeasuredFunction[] = [];
  const visit = (n: Node): void => {
    if (TS_FUNCTION_TYPES.has(n.type)) {
      out.push({ name: typeScriptName(n), node: n });
    }
    for (const child of n.namedChildren) {
      if (child) {
        visit(child);
      }
    }
  };
  visit(root);
  return out;
}

/**
 * @projectrevivesolutions/complexity
 *
 * Three complexity measures per function, from a tree-sitter syntax tree
 * the caller has already parsed: cyclomatic (McCabe), Cognitive Complexity
 * (Campbell), and MikeVan's Better Cognitive Complexity (MBCC). DeepTest and
 * UntangleIt both measure with this package, so the two never disagree
 * about the same function.
 *
 * The package holds no grammars and starts no parser. Hand it the function
 * nodes and their names; it hands back the numbers. docs/measures.md has
 * every rule and every reading that had to be chosen.
 */
export { CognitiveCounter, functionsInRecursionCycles } from './counter';
export type { BooleanRules, CognitiveScore, RunCharge } from './counter';
export { measurePython, cyclomaticOf as cyclomaticOfPython } from './python';
export { measureTypeScript, cyclomaticOf as cyclomaticOfTypeScript } from './typescript';
export { MEASURES } from './types';
export type { FunctionMeasures, MeasuredFunction } from './types';
export { findPythonFunctions, findTypeScriptFunctions } from './find';
export { extractScript, isSingleFileComponent } from './sfc';
export type { ScriptBlock, ScriptExtraction, ScriptLang } from './sfc';

/**
 * Python, on a tree-sitter tree: cyclomatic, Campbell, and MBCC per function.
 * The cognitive arithmetic is in counter.ts; this file only says what each
 * Python node is, and counts McCabe's forks.
 *
 * Mapping (see the shared file for the rule each word means):
 *
 *   if / elif / else        one chain: Campbell charges the if as structural
 *                           and each later branch as hybrid; MBCC charges
 *                           the k-th branch k + nesting, unless the chain is
 *                           exclusive (one value against constants), which
 *                           costs one plus nesting like a match. Bodies one
 *                           deeper either way.
 *   for / while             structural; loop `else` is hybrid
 *   except                  structural; try / else / finally cost nothing
 *   match                   structural, once, however many cases
 *   x if c else y           structural; all three parts one deeper
 *   a and b, a or b         one boolean sequence per run of the same operator
 *   lambda, nested def      no increment; contents one level deeper
 *   nested class            no increment; its body one level deeper
 *   with                    nothing
 *   comprehensions          nothing. The whitepaper predates a ruling on
 *                           them and this is the reading that a
 *                           comprehension is a single expression, not a
 *                           loop the reader steps through. Marked as a
 *                           decision in docs/measures.md.
 *   recursion               +1 for each function on a call cycle within
 *                           the file, by name (f() or self.f())
 *
 * Ordered-operand rule inputs: a call, an `await`, or a walrus (:=) makes an
 * operand impure; attribute and subscript access reach into their leftmost
 * name.
 *
 * Exclusive-chain inputs: a condition is an exclusive test when it is
 * `x == C`, `C == x`, `x is C`, `x in (C, ...)`, or an `or` run of those on
 * the same x, where x is a name or an attribute path and C is a literal
 * (string, number, True, False, None), a literal tuple, list, or set of
 * literals, an attribute whose last segment is Capitalised or ALL_CAPS
 * (`Kind.A`, `Status.ACTIVE`), or an ALL_CAPS name.
 */
import type { Node } from 'web-tree-sitter';
import { BooleanRules, CognitiveCounter, functionsInRecursionCycles } from './counter';
import { FunctionMeasures, MeasuredFunction } from './types';

const STOP = new Set(['lambda', 'function_definition', 'class_definition']);
const IMPURE = new Set(['call', 'named_expression', 'await']);

const rules: BooleanRules = {
  booleanParts(node) {
    if (node.type !== 'boolean_operator') {
      return null;
    }
    const left = node.childForFieldName('left');
    const right = node.childForFieldName('right');
    const operator = node.childForFieldName('operator')?.text ?? 'and';
    return left && right ? { operator, left, right } : null;
  },
  isImpure: (node) => IMPURE.has(node.type),
  memberRoot(node) {
    if (node.type !== 'attribute' && node.type !== 'subscript') {
      return null;
    }
    let n: Node | null = node;
    while (n && (n.type === 'attribute' || n.type === 'subscript' || n.type === 'call')) {
      n = n.type === 'attribute' ? n.childForFieldName('object') : n.type === 'subscript' ? n.childForFieldName('value') : n.childForFieldName('function');
    }
    return n?.type === 'identifier' ? n.text : null;
  },
  identifierName: (node) => (node.type === 'identifier' ? node.text : null),
  stopsAt: (node) => STOP.has(node.type),
  exclusiveKey: (node) => exclusiveKey(node),
};

const LITERAL = new Set(['string', 'concatenated_string', 'integer', 'float', 'true', 'false', 'none']);
const CONSTANT_NAME = /^[A-Z][A-Z0-9_]*$|^[A-Z][A-Za-z0-9]*$/;

function isConstant(node: Node): boolean {
  if (LITERAL.has(node.type)) {
    return true;
  }
  if (node.type === 'unary_operator') {
    return node.namedChildren.every((c) => c === null || isConstant(c));
  }
  if (node.type === 'tuple' || node.type === 'list' || node.type === 'set' || node.type === 'parenthesized_expression') {
    return node.namedChildren.length > 0 && node.namedChildren.every((c) => c === null || isConstant(c));
  }
  if (node.type === 'attribute') {
    const last = node.childForFieldName('attribute')?.text ?? '';
    return CONSTANT_NAME.test(last);
  }
  return node.type === 'identifier' && /^[A-Z][A-Z0-9_]*$/.test(node.text);
}

function isDiscriminator(node: Node): boolean {
  return node.type === 'identifier' || (node.type === 'attribute' && !isConstant(node));
}

/** See the header: the discriminated value's text for an exclusive test, else null. */
function exclusiveKey(node: Node): string | null {
  if (node.type === 'parenthesized_expression') {
    const inner = node.namedChildren[0];
    return inner ? exclusiveKey(inner) : null;
  }
  if (node.type === 'boolean_operator') {
    if (node.childForFieldName('operator')?.text !== 'or') {
      return null;
    }
    const left = node.childForFieldName('left');
    const right = node.childForFieldName('right');
    const l = left ? exclusiveKey(left) : null;
    const r = right ? exclusiveKey(right) : null;
    return l !== null && l === r ? l : null;
  }
  if (node.type !== 'comparison_operator') {
    return null;
  }
  const operands = node.namedChildren.filter((c): c is Node => c !== null);
  const operators = node.childrenForFieldName('operators').map((o) => o?.text ?? '');
  if (operands.length !== 2 || operators.length !== 1) {
    return null;
  }
  const [a, b] = operands;
  const op = operators[0];
  if (op === '==' || op === 'is') {
    if (isDiscriminator(a) && isConstant(b)) {
      return a.text;
    }
    if (isConstant(a) && isDiscriminator(b)) {
      return b.text;
    }
    return null;
  }
  if (op === 'in' && isDiscriminator(a) && isConstant(b)) {
    return a.text;
  }
  return null;
}

class Walker {
  readonly counter = new CognitiveCounter(rules);

  visit(node: Node | null, nesting: number): void {
    if (!node) {
      return;
    }
    switch (node.type) {
      case 'if_statement':
        this.visitIf(node, nesting);
        return;
      case 'for_statement':
      case 'while_statement':
        this.visitLoop(node, nesting);
        return;
      case 'try_statement':
        this.visitTry(node, nesting);
        return;
      case 'match_statement':
        this.visitMatch(node, nesting);
        return;
      case 'conditional_expression':
        this.counter.structural(nesting);
        this.children(node, nesting + 1);
        return;
      case 'boolean_operator':
        for (const operand of this.counter.booleanSequence(node)) {
          this.visit(operand, nesting);
        }
        return;
      case 'lambda':
        this.visit(node.childForFieldName('body'), nesting + 1);
        return;
      case 'function_definition':
      case 'class_definition':
        this.visit(node.childForFieldName('body'), nesting + 1);
        return;
      default:
        this.children(node, nesting);
    }
  }

  private children(node: Node, nesting: number): void {
    for (const child of node.namedChildren) {
      if (child) {
        this.visit(child, nesting);
      }
    }
  }

  /** The whole if / elif / else chain as one unit, so the branch rule can see its length and shape. */
  private visitIf(node: Node, nesting: number): void {
    const conditions: Node[] = [];
    const bodies: Node[] = [];
    const ifCondition = node.childForFieldName('condition');
    if (ifCondition) {
      conditions.push(ifCondition);
    }
    bodies.push(node.childForFieldName('consequence')!);
    let hasElse = false;
    for (const alternative of node.childrenForFieldName('alternative')) {
      if (!alternative) {
        continue;
      }
      if (alternative.type === 'elif_clause') {
        const c = alternative.childForFieldName('condition');
        if (c) {
          conditions.push(c);
        }
        bodies.push(alternative.childForFieldName('consequence')!);
      } else {
        hasElse = true;
        bodies.push(alternative.childForFieldName('body')!);
      }
    }
    const branches = conditions.length + (hasElse ? 1 : 0);
    const keys = conditions.map((c) => rules.exclusiveKey(c));
    const exclusive = branches > 1 && keys.every((k) => k !== null && k === keys[0]);
    this.counter.branchChain(branches, nesting, exclusive);
    for (const condition of conditions) {
      this.visitCondition(condition, nesting, exclusive);
    }
    for (const body of bodies) {
      this.visit(body, nesting + 1);
    }
  }

  /** A condition in an exclusive chain is a case list: its `or` runs charge Campbell only. */
  private visitCondition(condition: Node, nesting: number, exclusive: boolean): void {
    if (!exclusive) {
      this.visit(condition, nesting);
      return;
    }
    const inner = condition.type === 'parenthesized_expression' ? condition.namedChildren[0] ?? condition : condition;
    if (inner.type === 'boolean_operator') {
      for (const operand of this.counter.booleanSequence(inner, 'campbell')) {
        this.visitCondition(operand, nesting, true);
      }
      return;
    }
    this.visit(inner, nesting);
  }

  private visitLoop(node: Node, nesting: number): void {
    this.counter.structural(nesting);
    for (const field of ['left', 'right', 'condition']) {
      this.visit(node.childForFieldName(field), nesting);
    }
    this.visit(node.childForFieldName('body'), nesting + 1);
    const alternative = node.childForFieldName('alternative');
    if (alternative) {
      this.counter.fundamental();
      this.visit(alternative.childForFieldName('body'), nesting + 1);
    }
  }

  private visitTry(node: Node, nesting: number): void {
    this.visit(node.childForFieldName('body'), nesting);
    for (const clause of node.namedChildren) {
      if (!clause) {
        continue;
      }
      if (clause.type === 'except_clause' || clause.type === 'except_group_clause') {
        this.counter.structural(nesting);
        this.visit(clause.childForFieldName('value'), nesting);
        this.visit(clause.namedChildren.find((c) => c?.type === 'block') ?? null, nesting + 1);
      } else if (clause.type === 'else_clause' || clause.type === 'finally_clause') {
        this.visit(clause.childForFieldName('body') ?? clause.namedChildren.find((c) => c?.type === 'block') ?? null, nesting);
      }
    }
  }

  private visitMatch(node: Node, nesting: number): void {
    this.counter.structural(nesting);
    this.visit(node.childForFieldName('subject'), nesting);
    for (const clause of node.childForFieldName('body')?.namedChildren ?? []) {
      if (clause?.type === 'case_clause') {
        this.visit(clause.childForFieldName('guard'), nesting + 1);
        this.visit(clause.childForFieldName('consequence'), nesting + 1);
      }
    }
  }
}

/** Names this function body calls as `name(...)`, `self.name(...)`, or `cls.name(...)`. */
function calledNames(body: Node | null): Set<string> {
  const names = new Set<string>();
  const visit = (n: Node): void => {
    if (n.type === 'call') {
      const fn = n.childForFieldName('function');
      if (fn?.type === 'identifier') {
        names.add(fn.text);
      } else if (fn?.type === 'attribute') {
        const object = fn.childForFieldName('object')?.text;
        const attribute = fn.childForFieldName('attribute')?.text;
        if ((object === 'self' || object === 'cls') && attribute) {
          names.add(attribute);
        }
      }
    }
    for (const child of n.namedChildren) {
      if (child) {
        visit(child);
      }
    }
  };
  if (body) {
    visit(body);
  }
  return names;
}

/**
 * McCabe cyclomatic complexity: 1 + every fork inside the function body,
 * nested functions and classes excluded (they are functions of their own).
 * Short circuits, ternaries, and comprehension clauses always count: this
 * is the published number, not a project's depth policy.
 */
export function cyclomaticOf(body: Node | null): number {
  if (!body) {
    return 1;
  }
  let count = 0;
  const visit = (n: Node): void => {
    if (n.type === 'function_definition' || n.type === 'class_definition') {
      return;
    }
    switch (n.type) {
      case 'if_statement':
      case 'elif_clause':
      case 'for_statement':
      case 'while_statement':
      case 'except_clause':
      case 'except_group_clause':
      case 'case_clause':
      case 'boolean_operator':
      case 'conditional_expression':
      case 'for_in_clause':
      case 'if_clause':
        count += 1;
        break;
      default:
        break;
    }
    for (const child of n.namedChildren) {
      if (child) {
        visit(child);
      }
    }
  };
  visit(body);
  return 1 + count;
}

/**
 * All three measures for every function in a file, in the order given.
 * Recursion cycles are found across the whole list first, which is why
 * the input is the file's functions and not one function at a time.
 */
export function measurePython(functions: MeasuredFunction[]): FunctionMeasures[] {
  const calls = new Map<string, Set<string>>();
  for (const fn of functions) {
    const existing = calls.get(fn.name) ?? new Set<string>();
    for (const callee of calledNames(fn.node.childForFieldName('body'))) {
      existing.add(callee);
    }
    calls.set(fn.name, existing);
  }
  const recursive = functionsInRecursionCycles(calls);
  return functions.map((fn) => {
    const body = fn.node.childForFieldName('body');
    const walker = new Walker();
    walker.visit(body, 0);
    if (recursive.has(fn.name)) {
      walker.counter.fundamental();
    }
    return { cyclomatic: cyclomaticOf(body), ...walker.counter.score };
  });
}

/**
 * Single-file components: the script blocks of a .vue or .svelte file,
 * lifted out so a TypeScript or JavaScript grammar can parse them, with
 * every line number left where it was.
 *
 * The trick is not to extract at all. The result is the whole file with
 * everything outside the script blocks blanked out, character for
 * character, newlines kept. Line and column numbers in the parsed tree are
 * then the line and column numbers in the editor, so a route, a depth, a
 * function's start line, and a coverage line all point at the same place
 * without a translation table that could be wrong.
 *
 * A file may carry more than one block: Vue allows `<script>` beside
 * `<script setup>`, Svelte allows `<script module>` beside `<script>`. All
 * of them are kept; each is a module-level sequence of statements, and a
 * grammar parses them one after another without complaint. The template
 * half of the file is not parsed here. Its `v-if` and `{#if}` are decisions
 * a reader has to understand, and they wait for a later slot; the lines are
 * reported so a caller can count them as declarations (covered or not, but
 * never scored for density).
 */

export type ScriptLang = 'typescript' | 'tsx' | 'javascript';

export interface ScriptBlock {
  /** First line of the block's content, 1-based (the line after the opening tag, usually). */
  startLine: number;
  /** Last line of the block's content, 1-based. */
  endLine: number;
  lang: ScriptLang;
}

export interface ScriptExtraction {
  /** The file with everything outside the script blocks replaced by spaces; same length, same newlines. */
  source: string;
  /** The grammar to parse `source` with: tsx if any block asks for it, typescript if any block is ts, else javascript. */
  lang: ScriptLang;
  blocks: ScriptBlock[];
  /** Every line, 1-based, that lies outside the script blocks. */
  outside: Set<number>;
  /** Total line count of the file. */
  lines: number;
}

const SCRIPT_TAG = /<script\b([^>]*)>/gi;
const SCRIPT_END = /<\/script\s*>/gi;

function langOf(attributes: string): ScriptLang {
  const m = /\blang\s*=\s*["']?\s*([a-z]+)/i.exec(attributes);
  const value = m?.[1]?.toLowerCase();
  if (value === 'tsx') {
    return 'tsx';
  }
  if (value === 'ts' || value === 'typescript') {
    return 'typescript';
  }
  return 'javascript';
}

function lineAt(text: string, offset: number): number {
  let line = 1;
  for (let i = 0; i < offset && i < text.length; i += 1) {
    if (text.charCodeAt(i) === 10) {
      line += 1;
    }
  }
  return line;
}

/** True for the extensions this module reads. */
export function isSingleFileComponent(relativePath: string): boolean {
  return /\.(vue|svelte)$/i.test(relativePath);
}

/**
 * The script blocks of a single-file component. Returns undefined when the
 * file has no script block at all (a template-only component), so the
 * caller can treat every line as outside.
 */
export function extractScript(text: string): ScriptExtraction | undefined {
  const blocks: Array<{ start: number; end: number; lang: ScriptLang }> = [];
  SCRIPT_TAG.lastIndex = 0;
  let open: RegExpExecArray | null;
  while ((open = SCRIPT_TAG.exec(text)) !== null) {
    const contentStart = open.index + open[0].length;
    SCRIPT_END.lastIndex = contentStart;
    const close = SCRIPT_END.exec(text);
    if (!close) {
      break;
    }
    blocks.push({ start: contentStart, end: close.index, lang: langOf(open[1] ?? '') });
    SCRIPT_TAG.lastIndex = close.index + close[0].length;
  }
  if (blocks.length === 0) {
    return undefined;
  }
  const chars: string[] = Array.from(text, (c) => (c === "\n" || c === "\r" ? c : " "));
  for (const b of blocks) {
    for (let i = b.start; i < b.end; i += 1) {
      chars[i] = text[i] as string;
    }
  }
  const source = chars.join('');
  const totalLines = text.split('\n').length;
  const inside = new Set<number>();
  const out: ScriptBlock[] = [];
  for (const b of blocks) {
    // The content begins right after `>`; if that is the end of the tag's
    // line, the first content line is the next one.
    const startLine = text[b.start] === '\n' || (text[b.start] === '\r' && text[b.start + 1] === '\n') ? lineAt(text, b.start) + 1 : lineAt(text, b.start);
    const endLine = lineAt(text, Math.max(b.start, b.end - 1));
    for (let l = startLine; l <= endLine; l += 1) {
      inside.add(l);
    }
    out.push({ startLine, endLine, lang: b.lang });
  }
  const outside = new Set<number>();
  for (let l = 1; l <= totalLines; l += 1) {
    if (!inside.has(l)) {
      outside.add(l);
    }
  }
  const lang: ScriptLang = out.some((b) => b.lang === 'tsx') ? 'tsx' : out.some((b) => b.lang === 'typescript') ? 'typescript' : 'javascript';
  return { source, lang, blocks: out, outside, lines: totalLines };
}

import type { Node } from 'web-tree-sitter';

/** One function to measure: its name (for recursion cycles) and its tree-sitter node. */
export interface MeasuredFunction {
  name: string;
  node: Node;
}

/** The three numbers every tool in MikeVan's AI Development Toolkit reads. */
export interface FunctionMeasures {
  /** McCabe cyclomatic complexity: 1 + forks. "Ways through" in the tools. */
  cyclomatic: number;
  /** Cognitive Complexity as published by Campbell (SonarSource, 2018). "Tangle (Campbell)". */
  campbell: number;
  /** MikeVan's Better Cognitive Complexity. "Tangle (MBCC)". */
  mbcc: number;
}

/** Names and sources, so every tool prints the same words. */
export const MEASURES = {
  cyclomatic: {
    key: 'cyclomatic',
    name: 'Cyclomatic complexity',
    plain: 'ways through',
    source: 'McCabe, T. J. "A Complexity Measure." IEEE Transactions on Software Engineering, vol. SE-2, no. 4, 1976. https://doi.org/10.1109/TSE.1976.233837',
  },
  campbell: {
    key: 'campbell',
    name: 'Cognitive Complexity',
    plain: 'tangle (Campbell)',
    source: 'Campbell, G. A. "Cognitive Complexity: A New Way of Measuring Understandability." SonarSource, 2018. https://www.sonarsource.com/docs/CognitiveComplexity.pdf',
  },
  mbcc: {
    key: 'mbcc',
    name: "MikeVan's Better Cognitive Complexity",
    short: 'MBCC',
    plain: 'tangle (MBCC)',
    source: 'Van Geertruy, M. "MikeVan\'s Better Cognitive Complexity." Project Revive Solutions, 2026. https://projectrevivesolutions.com',
  },
} as const;

/**
 * TypeScript and JavaScript, on a tree-sitter tree: cyclomatic, Campbell,
 * and MBCC per function. The cognitive arithmetic is in counter.ts; this
 * file only says what each node is, and counts McCabe's forks. The
 * typescript, tsx, and javascript grammars share node names, so one file
 * serves all three.
 *
 * Mapping:
 *
 *   if / else if / else      one chain: Campbell charges the if as structural
 *                            and each later branch as hybrid; MBCC charges
 *                            the k-th branch k + nesting, unless the chain
 *                            is exclusive (one value against constants),
 *                            which costs one plus nesting like a switch.
 *                            Bodies one deeper either way.
 *   for / for-in / for-of / while / do   structural
 *   switch                   structural, once, however many cases
 *   catch                    structural; try and finally cost nothing
 *   c ? x : y                structural; all three parts one deeper
 *   a && b, a || b           one boolean sequence per run of the same operator
 *   a ?? b, a?.b             nothing (the whitepaper excludes null-coalescing)
 *   break LABEL, continue LABEL   +1, no nesting
 *   arrow, function expression, method, nested class   no increment; contents one deeper
 *   recursion                +1 for each function on a call cycle within
 *                            the file, by name (f() or this.f())
 *
 * Ordered-operand rule inputs: a call, `new`, `await`, `yield`, an
 * assignment, or ++/-- makes an operand impure; member and subscript
 * access reach into their leftmost name (`this` counts as a name).
 *
 * Exclusive-chain inputs: a condition is an exclusive test when it is
 * `x === C`, `x == C`, `C === x`, or an `||` run of those on the same x,
 * where x is a name or a member path (`this.kind`, `event.type`) and C is a
 * literal (string, number, true, false, null, undefined), a member
 * expression whose last segment is Capitalised or ALL_CAPS (`Kind.A`,
 * `Status.ACTIVE`), or an ALL_CAPS name.
 */
import type { Node } from 'web-tree-sitter';
import { BooleanRules, CognitiveCounter, functionsInRecursionCycles } from './counter';
import { FunctionMeasures, MeasuredFunction } from './types';

const FUNCTION_TYPES = new Set(['function_declaration', 'function_expression', 'arrow_function', 'method_definition', 'generator_function', 'generator_function_declaration', 'function']);
const CLASS_TYPES = new Set(['class_declaration', 'class', 'abstract_class_declaration']);
const IMPURE = new Set(['call_expression', 'new_expression', 'await_expression', 'yield_expression', 'assignment_expression', 'augmented_assignment_expression', 'update_expression']);
const BOOLEAN = new Set(['&&', '||']);

const rules: BooleanRules = {
  booleanParts(node) {
    if (node.type !== 'binary_expression') {
      return null;
    }
    const operator = node.childForFieldName('operator')?.text ?? '';
    if (!BOOLEAN.has(operator)) {
      return null;
    }
    const left = node.childForFieldName('left');
    const right = node.childForFieldName('right');
    return left && right ? { operator, left, right } : null;
  },
  isImpure: (node) => IMPURE.has(node.type),
  memberRoot(node) {
    if (node.type !== 'member_expression' && node.type !== 'subscript_expression') {
      return null;
    }
    let n: Node | null = node;
    while (n && (n.type === 'member_expression' || n.type === 'subscript_expression' || n.type === 'call_expression' || n.type === 'non_null_expression')) {
      n = n.type === 'call_expression' ? n.childForFieldName('function') : n.type === 'non_null_expression' ? n.namedChildren[0] ?? null : n.childForFieldName('object');
    }
    return n && (n.type === 'identifier' || n.type === 'this') ? n.text : null;
  },
  identifierName: (node) => (node.type === 'identifier' || node.type === 'this' ? node.text : null),
  stopsAt: (node) => FUNCTION_TYPES.has(node.type) || CLASS_TYPES.has(node.type),
  exclusiveKey: (node) => exclusiveKey(node),
};

const LITERAL = new Set(['string', 'number', 'true', 'false', 'null', 'undefined']);
const CONSTANT_NAME = /^[A-Z][A-Z0-9_]*$|^[A-Z][A-Za-z0-9]*$/;

function isConstant(node: Node): boolean {
  if (LITERAL.has(node.type)) {
    return true;
  }
  if (node.type === 'unary_expression') {
    return node.namedChildren.every((c) => c === null || isConstant(c));
  }
  if (node.type === 'member_expression') {
    const last = node.childForFieldName('property')?.text ?? '';
    return CONSTANT_NAME.test(last);
  }
  return node.type === 'identifier' && /^[A-Z][A-Z0-9_]*$/.test(node.text);
}

function isDiscriminator(node: Node): boolean {
  return node.type === 'identifier' || node.type === 'this' || (node.type === 'member_expression' && !isConstant(node));
}

/** See the header: the discriminated value's text for an exclusive test, else null. */
function exclusiveKey(node: Node): string | null {
  if (node.type === 'parenthesized_expression') {
    const inner = node.namedChildren[0];
    return inner ? exclusiveKey(inner) : null;
  }
  if (node.type !== 'binary_expression') {
    return null;
  }
  const operator = node.childForFieldName('operator')?.text ?? '';
  const left = node.childForFieldName('left');
  const right = node.childForFieldName('right');
  if (!left || !right) {
    return null;
  }
  if (operator === '||') {
    const l = exclusiveKey(left);
    const r = exclusiveKey(right);
    return l !== null && l === r ? l : null;
  }
  if (operator !== '===' && operator !== '==') {
    return null;
  }
  if (isDiscriminator(left) && isConstant(right)) {
    return left.text;
  }
  if (isConstant(left) && isDiscriminator(right)) {
    return right.text;
  }
  return null;
}

class Walker {
  readonly counter = new CognitiveCounter(rules);

  visit(node: Node | null, nesting: number): void {
    if (!node) {
      return;
    }
    if (FUNCTION_TYPES.has(node.type) || CLASS_TYPES.has(node.type)) {
      this.visit(node.childForFieldName('body'), nesting + 1);
      return;
    }
    switch (node.type) {
      case 'if_statement':
        this.visitIfChain(node, nesting);
        return;
      case 'for_statement':
      case 'for_in_statement':
      case 'while_statement':
      case 'do_statement':
        this.counter.structural(nesting);
        for (const field of ['initializer', 'condition', 'increment', 'left', 'right']) {
          this.visit(node.childForFieldName(field), nesting);
        }
        this.visit(node.childForFieldName('body'), nesting + 1);
        return;
      case 'switch_statement':
        this.counter.structural(nesting);
        this.visit(node.childForFieldName('value'), nesting);
        for (const clause of node.childForFieldName('body')?.namedChildren ?? []) {
          if (clause) {
            this.children(clause, nesting + 1);
          }
        }
        return;
      case 'try_statement':
        this.visit(node.childForFieldName('body'), nesting);
        this.visitCatch(node.childForFieldName('handler'), nesting);
        this.visit(node.childForFieldName('finalizer')?.childForFieldName('body') ?? null, nesting);
        return;
      case 'ternary_expression':
        this.counter.structural(nesting);
        this.children(node, nesting + 1);
        return;
      case 'binary_expression':
        if (rules.booleanParts(node)) {
          for (const operand of this.counter.booleanSequence(node)) {
            this.visit(operand, nesting);
          }
          return;
        }
        this.children(node, nesting);
        return;
      case 'break_statement':
      case 'continue_statement':
        if (node.childForFieldName('label')) {
          this.counter.fundamental();
        }
        return;
      default:
        this.children(node, nesting);
    }
  }

  private children(node: Node, nesting: number): void {
    for (const child of node.namedChildren) {
      if (child) {
        this.visit(child, nesting);
      }
    }
  }

  /**
   * The whole if / else if / else chain as one unit, so the branch rule can
   * see its length and shape. An `else` whose statement is an `if` is the
   * next link in the chain; any other `else` ends it.
   */
  private visitIfChain(node: Node, nesting: number): void {
    const conditions: Node[] = [];
    const bodies: (Node | null)[] = [];
    let hasElse = false;
    let current: Node | null = node;
    while (current) {
      const condition = current.childForFieldName('condition');
      if (condition) {
        conditions.push(condition);
      }
      bodies.push(current.childForFieldName('consequence'));
      const alternative = current.childForFieldName('alternative');
      if (!alternative) {
        break;
      }
      // alternative is an else_clause holding either an if_statement (else if) or a statement.
      const inner: Node | null = alternative.namedChildren[0] ?? null;
      if (inner?.type === 'if_statement') {
        current = inner;
      } else {
        hasElse = true;
        bodies.push(inner);
        break;
      }
    }
    const branches = conditions.length + (hasElse ? 1 : 0);
    const keys = conditions.map((c) => rules.exclusiveKey(c));
    const exclusive = branches > 1 && keys.every((k) => k !== null && k === keys[0]);
    this.counter.branchChain(branches, nesting, exclusive);
    for (const condition of conditions) {
      this.visitCondition(condition, nesting, exclusive);
    }
    for (const body of bodies) {
      this.visit(body, nesting + 1);
    }
  }

  /** A condition in an exclusive chain is a case list: its `||` runs charge Campbell only. */
  private visitCondition(condition: Node, nesting: number, exclusive: boolean): void {
    if (!exclusive) {
      this.visit(condition, nesting);
      return;
    }
    const inner = condition.type === 'parenthesized_expression' ? condition.namedChildren[0] ?? condition : condition;
    if (inner.type === 'binary_expression' && rules.booleanParts(inner)) {
      for (const operand of this.counter.booleanSequence(inner, 'campbell')) {
        this.visitCondition(operand, nesting, true);
      }
      return;
    }
    this.visit(inner, nesting);
  }

  private visitCatch(handler: Node | null, nesting: number): void {
    if (!handler) {
      return;
    }
    this.counter.structural(nesting);
    this.visit(handler.childForFieldName('body'), nesting + 1);
  }
}

/** Names this function body calls as `name(...)` or `this.name(...)`. */
function calledNames(body: Node | null): Set<string> {
  const names = new Set<string>();
  const visit = (n: Node): void => {
    if (n.type === 'call_expression') {
      const fn = n.childForFieldName('function');
      if (fn?.type === 'identifier') {
        names.add(fn.text);
      } else if (fn?.type === 'member_expression' && fn.childForFieldName('object')?.type === 'this') {
        const property = fn.childForFieldName('property')?.text;
        if (property) {
          names.add(property);
        }
      }
    }
    for (const child of n.namedChildren) {
      if (child) {
        visit(child);
      }
    }
  };
  if (body) {
    visit(body);
  }
  return names;
}

const SHORT_CIRCUIT = new Set(['&&', '||', '??']);

/**
 * McCabe cyclomatic complexity: 1 + every fork inside the function body,
 * nested functions and classes excluded. `??` counts here (it is a fork the
 * machine takes) although Cognitive Complexity charges nothing for it.
 */
export function cyclomaticOf(body: Node | null): number {
  if (!body) {
    return 1;
  }
  let count = 0;
  const visit = (n: Node): void => {
    if (FUNCTION_TYPES.has(n.type) || CLASS_TYPES.has(n.type)) {
      return;
    }
    switch (n.type) {
      case 'if_statement':
      case 'for_statement':
      case 'for_in_statement':
      case 'while_statement':
      case 'do_statement':
      case 'catch_clause':
      case 'switch_case':
      case 'ternary_expression':
        count += 1;
        break;
      case 'binary_expression':
        if (SHORT_CIRCUIT.has(n.childForFieldName('operator')?.text ?? '')) {
          count += 1;
        }
        break;
      default:
        break;
    }
    for (const child of n.namedChildren) {
      if (child) {
        visit(child);
      }
    }
  };
  visit(body);
  return 1 + count;
}

/** All three measures for every function in a file, in the order given. */
export function measureTypeScript(functions: MeasuredFunction[]): FunctionMeasures[] {
  const calls = new Map<string, Set<string>>();
  for (const fn of functions) {
    const existing = calls.get(fn.name) ?? new Set<string>();
    for (const callee of calledNames(fn.node.childForFieldName('body'))) {
      existing.add(callee);
    }
    calls.set(fn.name, existing);
  }
  const recursive = functionsInRecursionCycles(calls);
  return functions.map((fn) => {
    const body = fn.node.childForFieldName('body');
    const walker = new Walker();
    walker.visit(body, 0);
    if (recursive.has(fn.name)) {
      walker.counter.fundamental();
    }
    return { cyclomatic: cyclomaticOf(body), ...walker.counter.score };
  });
}

/**
 * Cognitive Complexity, checked against the rules and worked examples in
 * Campbell, "Cognitive Complexity: A New Way of Measuring Understandability",
 * SonarSource, 2018, and against MikeVan's Better Cognitive Complexity
 * (MBCC). Each test names the rule it pins down. Cyclomatic is checked in
 * the same breath so the three never drift apart.
 */
import { beforeAll, test } from 'vitest';
import assert from 'node:assert/strict';
import type { Parser } from 'web-tree-sitter';
import { parserFor } from './treeSitter';
import { findPythonFunctions, findTypeScriptFunctions, functionsInRecursionCycles, measurePython, measureTypeScript } from '../src';

let py: Parser;
let ts: Parser;

beforeAll(async () => {
  py = await parserFor('python');
  ts = await parserFor('typescript');
});

/** [cyclomatic, campbell, mbcc] for the named function, or the first one. */
function pyScore(source: string, name?: string): [number, number, number] {
  const tree = py.parse(source);
  assert.ok(tree, 'parse failed');
  const functions = findPythonFunctions(tree.rootNode);
  const measures = measurePython(functions);
  const i = name ? functions.findIndex((f) => f.name === name) : 0;
  assert.ok(i >= 0 && measures[i], `function ${name ?? '#0'} not found`);
  return [measures[i].cyclomatic, measures[i].campbell, measures[i].mbcc];
}

function tsScore(source: string, name?: string): [number, number, number] {
  const tree = ts.parse(source);
  assert.ok(tree, 'parse failed');
  const functions = findTypeScriptFunctions(tree.rootNode);
  const measures = measureTypeScript(functions);
  const i = name ? functions.findIndex((f) => f.name === name) : 0;
  assert.ok(i >= 0 && measures[i], `function ${name ?? '#0'} not found`);
  return [measures[i].cyclomatic, measures[i].campbell, measures[i].mbcc];
}

// ---- Python -------------------------------------------------------------

test('py: a straight-line function scores 0, however long it is', () => {
  const body = Array.from({ length: 40 }, (_, i) => `    self.f${i} = x${i}`).join('\n');
  assert.deepEqual(pyScore(`def f(self, ${Array.from({ length: 40 }, (_, i) => `x${i}`).join(', ')}):\n${body}\n`), [1, 0, 0]);
});

test('py: one if is +1; a second if nested inside it is +2', () => {
  assert.deepEqual(pyScore('def f(a, b):\n    if a:\n        return 1\n    return 0\n'), [2, 1, 1]);
  assert.deepEqual(pyScore('def f(a, b):\n    if a:\n        if b:\n            return 1\n    return 0\n'), [3, 3, 3]);
});

test('py: elif and else are +1 each with no nesting charge under Campbell; MBCC charges the k-th branch k', () => {
  // Campbell: if +1, elif +1, else +1; the nested if inside else is +1 + 1 nesting = +2. Total 5.
  // MBCC: a, b are different facts, so the chain is ordered: 1 + 2 + 3, then the nested if +2. Total 8.
  const src = 'def f(a, b, c):\n    if a:\n        return 1\n    elif b:\n        return 2\n    else:\n        if c:\n            return 3\n    return 0\n';
  assert.deepEqual(pyScore(src), [4, 5, 8]);
});

test('py: ordered branches (the paper, section 5): four branches on different facts cost 1 + 2 + 3 + 4', () => {
  const src = 'def f(total, customer):\n    if total < 0:\n        return 1\n    elif customer.is_new:\n        return 2\n    elif discount_applies():\n        return 3\n    else:\n        return 4\n';
  assert.deepEqual(pyScore(src), [4, 4, 10]);
  // The same chain one level deep: Campbell charges nesting on the if only (+1); MBCC on every branch (+4).
  const nested = 'def f(go, total, customer):\n    if go:\n        if total < 0:\n            return 1\n        elif customer.is_new:\n            return 2\n        elif discount_applies():\n            return 3\n        else:\n            return 4\n    return 0\n';
  assert.deepEqual(pyScore(nested), [5, 6, 15]);
});

test('py: an exclusive chain on one value against constants is a match in disguise and costs one', () => {
  const src = 'def f(kind):\n    if kind == "a":\n        return 1\n    elif kind == "b":\n        return 2\n    elif kind == "c":\n        return 3\n    else:\n        return 4\n';
  assert.deepEqual(pyScore(src), [4, 4, 1]);
  // Constant on the left, `is None`, an attribute path as the value, enum members, and `in` a literal tuple all qualify.
  const forms = 'def f(self):\n    if "a" == self.kind:\n        return 1\n    elif self.kind is None:\n        return 2\n    elif self.kind == Kind.B:\n        return 3\n    elif self.kind in ("c", "d"):\n        return 4\n    return 0\n';
  assert.deepEqual(pyScore(forms), [5, 4, 1]);
  // An `or` run of tests on the same value is a case list: Campbell charges the run, MBCC does not.
  const cases = 'def f(kind):\n    if kind == "a" or kind == "b":\n        return 1\n    elif kind == "c":\n        return 2\n    return 0\n';
  assert.deepEqual(pyScore(cases), [4, 3, 1]);
  // A 28-case chain is still one: tangle measures depth, not breadth.
  const many = Array.from({ length: 28 }, (_, i) => `${i === 0 ? 'if' : 'elif'} kind == ${i}:\n        return ${i}`).join('\n    ');
  assert.deepEqual(pyScore(`def f(kind):\n    ${many}\n    return -1\n`), [29, 28, 1]);
});

test('py: a chain stops being exclusive the moment one branch tests a different fact', () => {
  // kind == "a" / kind == "b" / else ok: exclusive. Add `elif total < 0` and the reader must hold the failures again.
  const src = 'def f(kind, total):\n    if kind == "a":\n        return 1\n    elif total < 0:\n        return 2\n    elif kind == "b":\n        return 3\n    return 0\n';
  assert.deepEqual(pyScore(src), [4, 3, 6]);
  // A call on the tested side is not a constant test.
  const call = 'def f(kind):\n    if kind == "a":\n        return 1\n    elif kind == pick():\n        return 2\n    return 0\n';
  assert.deepEqual(pyScore(call), [3, 2, 3]);
});

test('py: a flat match with many cases costs 1; cyclomatic charges every case', () => {
  const cases = Array.from({ length: 12 }, (_, i) => `        case ${i}:\n            return ${i}`).join('\n');
  const src = `def f(x):\n    match x:\n${cases}\n    return -1\n`;
  assert.deepEqual(pyScore(src), [13, 1, 1]);
});

test('py: loops are structural, and a loop else is hybrid', () => {
  // for +1, while nested +2, for-else +1. Total 4.
  const src = 'def f(xs):\n    for x in xs:\n        while x:\n            x -= 1\n    else:\n        return 0\n    return 1\n';
  assert.deepEqual(pyScore(src), [3, 4, 4]);
});

test('py: try costs nothing, except is structural, finally and else cost nothing', () => {
  // except +1, the if inside it +2. Total 3.
  const src = 'def f():\n    try:\n        g()\n    except ValueError as e:\n        if e:\n            raise\n    else:\n        h()\n    finally:\n        k()\n';
  assert.deepEqual(pyScore(src), [3, 3, 3]);
});

test('py: whitepaper boolean runs: a and b and c is +1; a and b or c is +2', () => {
  assert.deepEqual(pyScore('def f(a, b, c):\n    return a and b and c\n'), [3, 1, 1]);
  assert.deepEqual(pyScore('def f(a, b, c):\n    return a and b or c\n'), [3, 2, 2]);
  // The whitepaper example: a && b && c || d || e && f is three sequences.
  assert.deepEqual(pyScore('def f(a, b, c, d, e, g):\n    return a and b and c or d or e and g\n'), [6, 3, 3]);
});

test('py: parentheses and not start a fresh sequence', () => {
  // a and (b or c): one and-run, one or-run inside. Published 2.
  assert.deepEqual(pyScore('def f(a, b, c):\n    return a and (b or c)\n'), [3, 2, 2]);
  assert.deepEqual(pyScore('def f(a, b, c):\n    return a and not (b or c)\n'), [3, 2, 2]);
});

test('py: MBCC: independent pure operands still cost one', () => {
  assert.deepEqual(pyScore('def f(a, b, c):\n    if a > 0 and b > 0 and c > 0:\n        return 1\n    return 0\n'), [4, 2, 2]);
});

test('py: MBCC: a later operand reaching into a name an earlier one tested costs one per operand', () => {
  // member is not None and member.dues is not None and member.dues.paid > cutoff
  // published: if +1, one run +1 = 2. ordered: if +1, three operands +3 = 4.
  const src = 'def f(member, cutoff):\n    if member is not None and member.dues is not None and member.dues.paid > cutoff:\n        return 1\n    return 0\n';
  assert.deepEqual(pyScore(src), [4, 2, 4]);
});

test('py: MBCC: a call anywhere in the run makes it ordered', () => {
  const src = 'def f(xs):\n    if xs and len(xs) > 3:\n        return 1\n    return 0\n';
  assert.deepEqual(pyScore(src), [3, 2, 3]);
});

test('py: MBCC: a walrus makes it ordered', () => {
  const src = 'def f(xs):\n    if xs and (n := count(xs)):\n        return n\n    return 0\n';
  assert.deepEqual(pyScore(src), [3, 2, 3]);
});

test('py: MBCC applies per run, not per expression', () => {
  // (m and m.x) or flag: the and-run is ordered (2), the or-run is independent (1). Published 2, ordered 3.
  const src = 'def f(m, flag):\n    return (m and m.x) or flag\n';
  assert.deepEqual(pyScore(src), [3, 2, 3]);
});

test('py: ternary is structural, and nests', () => {
  // outer ternary +1, inner ternary +2. Total 3.
  assert.deepEqual(pyScore('def f(a, b):\n    return 1 if a else (2 if b else 3)\n'), [3, 3, 3]);
});

test('py: a lambda or nested def adds nesting but no increment', () => {
  // if inside a lambda: +1 for the if... a ternary at nesting 1 = +2. Nothing for the lambda.
  assert.deepEqual(pyScore('def f(xs):\n    return sorted(xs, key=lambda x: 1 if x else 0)\n', 'f'), [2, 2, 2]);
  // nested def: the inner if is one level deeper, +2. The inner function is also scored on its own at +1.
  const src = 'def outer(a):\n    def inner(b):\n        if b:\n            return 1\n        return 0\n    return inner(a)\n';
  assert.deepEqual(pyScore(src, 'outer'), [1, 2, 2]);
  assert.deepEqual(pyScore(src, 'inner'), [2, 1, 1]);
});

test('py: comprehensions cost nothing here, while cyclomatic counts each clause', () => {
  assert.deepEqual(pyScore('def f(xs):\n    return [x for x in xs if x]\n'), [3, 0, 0]);
});

test('py: recursion is +1 per function on a cycle, direct or mutual, by name', () => {
  assert.deepEqual(pyScore('def fact(n):\n    if n < 2:\n        return 1\n    return n * fact(n - 1)\n'), [2, 2, 2]);
  const mutual = 'def even(n):\n    return n == 0 or odd(n - 1)\n\ndef odd(n):\n    return n != 0 and even(n - 1)\n\ndef alone(n):\n    return even(n)\n';
  // even: or-run +1 (ordered: has a call, so 2), recursion +1. odd: the same. alone: nothing.
  assert.deepEqual(pyScore(mutual, 'even'), [2, 2, 3]);
  assert.deepEqual(pyScore(mutual, 'odd'), [2, 2, 3]);
  assert.deepEqual(pyScore(mutual, 'alone'), [1, 0, 0]);
  assert.deepEqual(pyScore('class C:\n    def walk(self, n):\n        if n:\n            self.walk(n - 1)\n', 'walk'), [2, 2, 2]);
});

test('py: the whitepaper-style deep nest charges more the deeper it goes', () => {
  // if +1, for +2, if +3, and-run +1 = 7. Cyclomatic is 5.
  const src = 'def f(xs, a, b):\n    if a:\n        for x in xs:\n            if x and b:\n                return x\n    return None\n';
  assert.deepEqual(pyScore(src), [5, 7, 7]);
});

// ---- TypeScript / JavaScript -------------------------------------------

test('ts: a straight-line function scores 0', () => {
  assert.deepEqual(tsScore('function f(a: number) {\n  const b = a + 1;\n  return b;\n}\n'), [1, 0, 0]);
});

test('ts: else if and else are hybrid under Campbell; MBCC charges the k-th branch k', () => {
  // Campbell: if +1, else if +1, else +1, nested if inside else +2. Total 5. MBCC: 1 + 2 + 3, then +2. Total 8.
  const src = 'function f(a, b, c) {\n  if (a) { return 1; }\n  else if (b) { return 2; }\n  else { if (c) { return 3; } }\n  return 0;\n}\n';
  assert.deepEqual(tsScore(src), [4, 5, 8]);
});

test('ts: ordered branches (the paper, section 5): four branches on different facts cost 1 + 2 + 3 + 4', () => {
  const src = 'function f(total, customer) {\n  if (total < 0) { return 1; }\n  else if (customer.isNew) { return 2; }\n  else if (discountApplies()) { return 3; }\n  else { return 4; }\n}\n';
  assert.deepEqual(tsScore(src), [4, 4, 10]);
  const nested = 'function f(go, total, customer) {\n  if (go) {\n    if (total < 0) { return 1; }\n    else if (customer.isNew) { return 2; }\n    else if (discountApplies()) { return 3; }\n    else { return 4; }\n  }\n  return 0;\n}\n';
  assert.deepEqual(tsScore(nested), [5, 6, 15]);
});

test('ts: an exclusive chain on one value against constants is a switch in disguise and costs one', () => {
  const src = 'function f(kind) {\n  if (kind === "a") { return 1; }\n  else if (kind === "b") { return 2; }\n  else if (kind === "c") { return 3; }\n  else { return 4; }\n}\n';
  assert.deepEqual(tsScore(src), [4, 4, 1]);
  // this.kind as the value, enum members, ==, null, and an || case list.
  const forms = 'class A { f() {\n  if (this.kind === Kind.A || this.kind === Kind.B) { return 1; }\n  else if (this.kind == null) { return 2; }\n  else if (MAX === this.kind) { return 3; }\n  return 0;\n} }\n';
  assert.deepEqual(tsScore(forms), [5, 4, 1]);
});

test('ts: a chain stops being exclusive the moment one branch tests a different fact', () => {
  const src = 'function f(kind, total) {\n  if (kind === "a") { return 1; }\n  else if (total < 0) { return 2; }\n  else if (kind === "b") { return 3; }\n  return 0;\n}\n';
  assert.deepEqual(tsScore(src), [4, 3, 6]);
});

test('ts: a flat switch costs 1 whatever the number of cases', () => {
  const cases = Array.from({ length: 12 }, (_, i) => `    case ${i}: return ${i};`).join('\n');
  const src = `function f(x) {\n  switch (x) {\n${cases}\n    default: return -1;\n  }\n}\n`;
  assert.deepEqual(tsScore(src), [13, 1, 1]);
});

test('ts: loops, catch, ternary, and labeled jumps', () => {
  // for +1, while +2, catch +1, ternary in catch body +2 = 6.
  const src = 'function f(xs) {\n  for (const x of xs) {\n    while (x) { x--; }\n  }\n  try { g(); } catch (e) { return e ? 1 : 0; } finally { h(); }\n}\n';
  assert.deepEqual(tsScore(src), [5, 6, 6]);
  // labeled continue is +1, plain break is nothing. outer for +1, inner for +2, if +3, continue LABEL +1 = 7.
  const labeled = 'function f(m) {\n  outer: for (const a of m) {\n    for (const b of a) {\n      if (b) { continue outer; }\n      break;\n    }\n  }\n}\n';
  assert.deepEqual(tsScore(labeled), [4, 7, 7]);
});

test('ts: whitepaper boolean runs, and ?? costs nothing', () => {
  assert.deepEqual(tsScore('function f(a, b, c, d, e, g) {\n  return a && b && c || d || e && g;\n}\n'), [6, 3, 3]);
  assert.deepEqual(tsScore('function f(a, b) {\n  return a ?? b;\n}\n'), [2, 0, 0]);
  assert.deepEqual(tsScore('function f(a, b, c) {\n  return a && !(b || c);\n}\n'), [3, 2, 2]);
});

test('ts: MBCC with this-rooted member access and calls', () => {
  // pure independent: published 1, ordered 1
  assert.deepEqual(tsScore('function f(a, b, c) {\n  return a > 0 && b > 0 && c > 0;\n}\n'), [3, 1, 1]);
  // user && user.profile && user.profile.name: ordered 3
  assert.deepEqual(tsScore('function f(user) {\n  return user && user.profile && user.profile.name;\n}\n'), [3, 1, 3]);
  // call inside: ordered
  assert.deepEqual(tsScore('function f(xs) {\n  return xs && xs.length > 0 && check(xs);\n}\n'), [3, 1, 3]);
  // this.x && this.x.y inside a method
  assert.deepEqual(tsScore('class C {\n  ok() {\n    return this.x && this.x.y;\n  }\n}\n', 'ok'), [2, 1, 2]);
});

test('ts: arrows add nesting but no increment; expression-bodied arrow with a ternary', () => {
  // ternary inside the arrow: nesting 1, so +2. The arrow itself is also its own function scoring +1.
  const src = 'function f(xs) {\n  return xs.map((x) => x ? 1 : 0);\n}\n';
  assert.deepEqual(tsScore(src, 'f'), [1, 2, 2]);
});

test('ts: recursion by name, direct and through this', () => {
  assert.deepEqual(tsScore('function fact(n) {\n  if (n < 2) { return 1; }\n  return n * fact(n - 1);\n}\n'), [2, 2, 2]);
  assert.deepEqual(tsScore('class T {\n  walk(n) {\n    if (n) { this.walk(n - 1); }\n  }\n}\n', 'walk'), [2, 2, 2]);
});

// ---- Shared -------------------------------------------------------------

test('recursion cycles: self loops and mutual cycles, not mere callers', () => {
  const calls = new Map<string, Set<string>>([
    ['a', new Set(['b'])],
    ['b', new Set(['a'])],
    ['c', new Set(['a'])],
    ['d', new Set(['d'])],
    ['e', new Set(['missing'])],
  ]);
  assert.deepEqual(Array.from(functionsInRecursionCycles(calls)).sort(), ['a', 'b', 'd']);
});

/**
 * Single-file components: the script blocks come out with their line
 * numbers intact, the template stays out, and the grammar is chosen from
 * the lang attribute.
 */
import { beforeAll, test } from 'vitest';
import assert from 'node:assert/strict';
import type { Parser } from 'web-tree-sitter';
import { parserFor } from './treeSitter';
import { extractScript, findTypeScriptFunctions, isSingleFileComponent, measureTypeScript } from '../src';

let ts: Parser;

beforeAll(async () => {
  ts = await parserFor('typescript');
});

const VUE = [
  '<script lang="ts">',                       // 1
  'import { ref } from "vue";',               // 2
  '',                                         // 3
  'export function pick(a: number): string {', // 4
  '  if (a > 0) {',                           // 5
  '    return "pos";',                        // 6
  '  } else if (a < 0) {',                    // 7
  '    return "neg";',                        // 8
  '  }',                                      // 9
  '  return "zero";',                         // 10
  '}',                                        // 11
  '</script>',                                // 12
  '',                                         // 13
  '<template>',                               // 14
  '  <p v-if="a > 0">{{ pick(a) }}</p>',      // 15
  '</template>',                              // 16
  '',                                         // 17
  '<style scoped>p { color: red }</style>',   // 18
].join('\n');

test('isSingleFileComponent by extension', () => {
  assert.equal(isSingleFileComponent('src/App.vue'), true);
  assert.equal(isSingleFileComponent('src/lib/X.svelte'), true);
  assert.equal(isSingleFileComponent('src/x.ts'), false);
});

test('a Vue block keeps its line numbers and blanks the template', () => {
  const x = extractScript(VUE);
  assert.ok(x);
  assert.equal(x.lang, 'typescript');
  assert.deepEqual(x.blocks, [{ startLine: 2, endLine: 11, lang: 'typescript' }]);
  assert.equal(x.source.length, VUE.length, 'same length');
  assert.equal(x.source.split('\n').length, VUE.split('\n').length, 'same line count');
  const lines = x.source.split('\n');
  assert.equal(lines[0].trim(), '', 'the opening tag is blanked');
  assert.equal(lines[3], 'export function pick(a: number): string {', 'line 4 is still line 4');
  assert.equal(lines[14].trim(), '', 'the template is blanked');
  assert.deepEqual(Array.from(x.outside).sort((a, b) => a - b), [1, 12, 13, 14, 15, 16, 17, 18]);
  assert.equal(x.lines, 18);
});

test('the blanked source parses, and the function sits on its real lines with the right numbers', () => {
  const x = extractScript(VUE)!;
  const tree = ts.parse(x.source);
  assert.ok(tree);
  const fns = findTypeScriptFunctions(tree.rootNode);
  assert.equal(fns.length, 1);
  assert.equal(fns[0].name, 'pick');
  assert.equal(fns[0].node.startPosition.row + 1, 4);
  assert.equal(fns[0].node.endPosition.row + 1, 11);
  const m = measureTypeScript(fns)[0];
  assert.deepEqual([m.cyclomatic, m.campbell, m.mbcc], [3, 2, 3]);
});

test('Svelte: a module block and an instance block are both kept, in order, and the lang is the stricter one', () => {
  const svelte = [
    '<script module>',              // 1
    '  export function a() { return 1; }', // 2
    '</script>',                    // 3
    '<script lang="ts">',           // 4
    '  let n: number = a();',       // 5
    '</script>',                    // 6
    '<h1>{n}</h1>',                 // 7
  ].join('\n');
  const x = extractScript(svelte)!;
  assert.equal(x.lang, 'typescript');
  assert.deepEqual(x.blocks.map((b) => [b.startLine, b.endLine, b.lang]), [[2, 2, 'javascript'], [5, 5, 'typescript']]);
  assert.deepEqual(Array.from(x.outside).sort((a, b) => a - b), [1, 3, 4, 6, 7]);
  const tree = ts.parse(x.source)!;
  assert.equal(findTypeScriptFunctions(tree.rootNode)[0].node.startPosition.row + 1, 2);
});

test('no script block at all: undefined, so the caller treats every line as outside', () => {
  assert.equal(extractScript('<template><p>hi</p></template>\n'), undefined);
});

test('content on the tag line, single quotes, tsx, and CRLF endings', () => {
  const text = "<script lang='tsx'>const f = () => <b/>;\r\n</script>\r\n<div/>\r\n";
  const x = extractScript(text)!;
  assert.equal(x.lang, 'tsx');
  assert.deepEqual(x.blocks, [{ startLine: 1, endLine: 1, lang: 'tsx' }]);
  assert.equal(x.source.length, text.length);
  assert.equal(x.source.split('\r\n')[0].trim(), 'const f = () => <b/>;');
  assert.deepEqual(Array.from(x.outside).sort((a, b) => a - b), [2, 3, 4]);
});

test('a script tag inside a template string or comment does not fool the closing search', () => {
  const text = '<script>\nconst s = "<script>";\nconst t = 1;\n</script>\n';
  const x = extractScript(text)!;
  assert.deepEqual(x.blocks.map((b) => [b.startLine, b.endLine]), [[2, 3]]);
});

/** Loads web-tree-sitter and the vendored grammars for the tests. The package itself ships neither. */
import { Language, Parser } from 'web-tree-sitter';
import * as fs from 'node:fs';
import * as path from 'node:path';

let ready: Promise<void> | undefined;

export async function parserFor(grammar: 'python' | 'typescript'): Promise<Parser> {
  const vendor = path.join(__dirname, '..', 'vendor');
  if (!ready) {
    const runtime = path.join(__dirname, '..', 'node_modules', 'web-tree-sitter', 'web-tree-sitter.wasm');
    ready = Parser.init({ locateFile: () => runtime }).then(() => undefined);
  }
  await ready;
  const language = await Language.load(fs.readFileSync(path.join(vendor, `tree-sitter-${grammar}.wasm`)));
  const parser = new Parser();
  parser.setLanguage(language);
  return parser;
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    include: ['test/**/*.test.ts'],
  },
});
